css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; border: calc(var(--loader-size) * .05) solid var(--accent); position: relative; animation: neon calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader::before { content: ''; position: absolute; inset: 18%; border-radius: 50%; border: calc(var(--loader-size) * .03) solid var(--accent-2); box-shadow: 0 0 calc(var(--loader-size) * .1) var(--accent-2), inset 0 0 calc(var(--loader-size) * .06) var(--accent-2); }
@keyframes neon { 0%, 100% { box-shadow: 0 0 calc(var(--loader-size) * .08) var(--accent), inset 0 0 calc(var(--loader-size) * .08) var(--accent); opacity: .7; } 50% { box-shadow: 0 0 calc(var(--loader-size) * .3) var(--accent), inset 0 0 calc(var(--loader-size) * .2) var(--accent); opacity: 1; } }
